import{_ as e,c as a,o as t,a6 as l}from"./chunks/framework.C2DR_BI-.js";const _=JSON.parse('{"title":"flex 弹性布局","description":"","frontmatter":{},"headers":[],"relativePath":"modules/web/css/flex.md","filePath":"modules/web/css/flex.md","lastUpdated":1773860220000}'),r={name:"modules/web/css/flex.md"},o=l('<h1 id="flex-弹性布局" tabindex="-1">flex 弹性布局 <a class="header-anchor" href="#flex-弹性布局" aria-label="Permalink to &quot;flex 弹性布局&quot;">​</a></h1><p>Flex（Flexible Box）即弹性布局，是一种CSS3提供的高效布局方式，用于在不同屏幕和设备下灵活排列、对齐和分配容器内的空间。它通过定义弹性容器（Flex Container）[&amp;和弹性项目（Flex Item）&amp;]，让元素在主轴和交叉轴上自由伸缩，轻松实现响应式设计。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><p>弹性容器：设置 display: flex 或 display: inline-flex 的元素。</p><p>弹性项目：容器的直接子元素。</p><p>主轴（main axis）：项目排列的主要方向，默认水平从左到右。</p><p>交叉轴（cross axis）：与主轴垂直的方向，默认垂直从上到下。</p><h2 id="常用容器属性" tabindex="-1">常用容器属性 <a class="header-anchor" href="#常用容器属性" aria-label="Permalink to &quot;常用容器属性&quot;">​</a></h2><p>flex-direction：设置主轴方向，如 row、column。</p><p>justify-content：主轴对齐方式，如 flex-start、center、space-between。</p><p>align-items：交叉轴对齐方式，如 flex-start、center、stretch。</p><p>flex-wrap：是否换行，如 nowrap、wrap。</p><p>align-content：多行在交叉轴的对齐方式，仅在换行时生效。</p><h2 id="常用项目属性" tabindex="-1">常用项目属性 <a class="header-anchor" href="#常用项目属性" aria-label="Permalink to &quot;常用项目属性&quot;">​</a></h2><p>order：项目排列顺序，数值越小越靠前。</p><p>flex-grow：放大比例，控制剩余空间分配。</p><p>flex-shrink：缩小比例，空间不足时的压缩比例。</p><p>flex-basis：分配空间前的初始大小。</p><p>flex：flex-grow flex-shrink flex-basis 的简写。</p><p>align-self：单个项目在交叉轴的对齐方式，可覆盖 align-items。</p><h2 id="优势与应用" tabindex="-1">优势与应用 <a class="header-anchor" href="#优势与应用" aria-label="Permalink to &quot;优势与应用&quot;">​</a></h2><p>Flex布局简化了传统float、position难以实现的垂直居中、等高列等需求，且天然支持响应式设计。常用于导航栏、卡片布局、多栏自适应等场景。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>设为Flex布局后，子元素的 float、clear、vertical-align 将失效。</p><p>在旧版浏览器中可能需要 -webkit- 前缀。</p>',25),i=[o];function s(n,p,c,d,f,x){return t(),a("div",null,i)}const m=e(r,[["render",s]]);export{_ as __pageData,m as default};
